//! Implicit-descendant one-compound has only; no general has or page-readiness claim.
use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
use kobo_web_document::style_tree::StyleTree;
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(css:&str,body:&str,lim:&Limits,s:&SnapshotState)->StyleTree{let h=format!("<!doctype html><style>{css}</style>{body}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],lim,None,SupplyBudget::CANONICAL,s)}
#[test]
fn browser_color_only_cascade8cases(){let html=include_str!("fixtures/desc_has_cascade.html");let t=kobo_web_document::parse_style_tree_with_state(html.as_bytes(),&[],&Limits::DEFAULT,None,SupplyBudget::CANONICAL,&snap());assert!(!t.unsupported && !t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0xff0000,0xff0000,0x0000ff,0x0000ff,0xff0000,0x0000ff,0x0000ff]);}
#[test]
fn missing_wrong_snapshot_autofocus_and_same_target(){let css=".absent:not(:where(:has(:focus))){color:red}";assert!(run(css,"<div><p></p></div>",&Limits::DEFAULT,&snap()).unsupported);let mut s=snap();s.input=Some(InputState::QuiescentCapture);assert!(run(css,"<div><p></p></div>",&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(css,"<div><p></p></div>",&Limits::DEFAULT,&s).unsupported);assert!(run(css,"<div><p autofocus></p></div>",&Limits::DEFAULT,&s).unsupported);let css="div:has(:link){color:red}";assert!(run(css,"<div><a href=x></a></div>",&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);assert!(!run(css,"<div><a href=x></a></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("child".into()));let t=run("div:has(:target){color:red}","<div><p id=child></p></div>",&Limits::DEFAULT,&s);assert!(!t.unsupported);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);}
#[test]
fn real_error_before_true_exhaustion_and_input_node_text_loss_refusal(){let b=format!("<div><p data-x='{}'></p><p data-x=aaaaab></p></div>","a".repeat(1000));let t=run("div:has([data-x*=aaaaab]){color:red}",&b,&Limits::DEFAULT,&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);for css in ["div:has(:empty){color:red}","div:not(:has(:empty)){color:red}","div:where(:has(:empty)){color:red}"]{for l in [Limits{max_input_bytes:55,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(css,"<div><p>x</p></div>",&l,&snap());assert!(t.truncated || t.unsupported);}}let h="<!doctype html><style>div:has(>p){color:red}</style><div><p></p></div>";assert!(kobo_web_document::parse_style_tree(h.as_bytes(),&[],&Limits::DEFAULT).unsupported);}
#[test]
#[ignore="measurement: DESC_HAS_LINES original439"]
fn public_original439_inventory(){let text=std::fs::read_to_string(std::env::var("DESC_HAS_LINES").unwrap()).unwrap();let s=SnapshotState{history:Some(HistoryState::FreshNoHistory),input:Some(InputState::QuiescentCapture),focus:Some(FocusState::UnfocusedInitial),target:Some(TargetState::FragmentFreeCapture)};let mut total=0;let mut refused=Vec::new();for(ix,l)in text.lines().enumerate(){total+=1;let t=run(&format!("{l}{{color:red}}"),"<div><p></p><span>x</span></div>",&Limits::DEFAULT,&s);let yes=!t.unsupported && !t.truncated;if !yes{refused.push(ix+1);}println!("DESC-HAS-PUBLIC line={} admitted={} truncated={} first={:?}",ix+1,yes,t.truncated,t.diagnostics.first_reason());}println!("DESC-HAS-PUBLIC total={} admitted={} refused={:?}",total,total-refused.len(),refused);assert_eq!(total,439);assert_eq!(refused,vec![270,274]);}

#[test] fn deep150_real_public_and_broad_exhaustion(){let b=format!("<div id=root>{}<p class=hit></p>{}</div>","<section>".repeat(150),"</section>".repeat(150));let t=run("#root:has(.hit){color:red}",&b,&Limits::DEFAULT,&snap());assert!(!t.unsupported && !t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0xff0000);for b in [format!("<div>{}</div>","<p></p>".repeat(500)),format!("<div>{}<p></p>{}</div>","<section>".repeat(1500),"</section>".repeat(1500))]{let t=run("div:has(.missing){color:red}",&b,&Limits{max_nodes:10000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);}}
#[test] fn real_global_spent_work_without_individual_fuel_exhaustion(){
 let one=format!("<div>{}</div>","<p></p>".repeat(50));
 let small=run("div:has(.missing){color:red}",&one,&Limits::DEFAULT,&snap());assert!(!small.truncated && !small.unsupported,"one traversal fits per-match fuel");
 let big=one.repeat(3000);let t=run("div:has(.missing){color:red}",&big,&Limits{max_input_bytes:4_000_000,max_nodes:200_000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::DomNodes),0);assert_eq!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::InputBytes),0);
}
